# validate_fused_dataset.py
# Analyzes and validates the .npy datasets generated by generate_fused_dataset.py.
#
# Checks:
#   - All expected files exist (data_time_domain, data_frequency_domain, labels, groups)
#   - Shape consistency: N identical across all four files
#   - Window dimensions: (N, target_n, 8*n_positions) time, (N, target_n//2, 8*n_positions) freq
#   - Channel count matches declared number of fused positions
#   - No NaN or Inf values in data arrays
#   - Label values are only 0 or 1
#   - Group IDs are integers in [1, 15]
#   - Class balance (fall vs non-fall) overall and per group
#   - Per-group sample count (every individual that should appear, does)
#   - Cross-check: compare sample counts vs the matching single-sensor datasets if available
#
# Usage:
#   python validate_fused_dataset.py [--name chest_left_right] [--output <dataset_root>]
#                                    [--target-size 450] [--positions chest left right]

import argparse
import os
import sys

import numpy as np

VALID_LABELS = {0, 1}
VALID_GROUPS = set(range(1, 16))

# ── CLI ───────────────────────────────────────────────────────────────────────
parser = argparse.ArgumentParser(description="Validate fused multi-sensor .npy datasets")
parser.add_argument(
    "--name", type=str, default=None,
    help="Subdirectory name of the fused dataset (default: <positions> joined by '_')",
)
parser.add_argument(
    "--positions", type=str, nargs="+", default=["chest", "left", "right"],
    choices=["chest", "left", "right"],
    help="Sensor positions that were fused (default: chest left right)",
)
parser.add_argument(
    "--output", type=str,
    default=os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "dataset"),
    help="Root dataset directory (contains the fused subdirectory)",
)
parser.add_argument(
    "--target-size", type=int, default=460,
    help="Expected window length after resampling (default: 460)",
)
args = parser.parse_args()

positions   = [p.lower() for p in args.positions]
target_n    = args.target_size
n_positions = len(positions)
n_channels  = 8 * n_positions
fused_name  = args.name or "_".join(positions)
dataset_root = os.path.abspath(args.output)
fused_root  = os.path.join(dataset_root, fused_name)

# ── Helpers ───────────────────────────────────────────────────────────────────
PASS = "  [PASS]"
FAIL = "  [FAIL]"
WARN = "  [WARN]"

def ok(msg):   print(f"{PASS} {msg}")
def fail(msg): print(f"{FAIL} {msg}"); global _any_fail; _any_fail = True
def warn(msg): print(f"{WARN} {msg}")

_any_fail = False


def check_finite(arr, name):
    n_nan = int(np.isnan(arr).sum())
    n_inf = int(np.isinf(arr).sum())
    if n_nan > 0:
        fail(f"{name}: contains {n_nan} NaN values")
    if n_inf > 0:
        fail(f"{name}: contains {n_inf} Inf values")
    if n_nan == 0 and n_inf == 0:
        ok(f"{name}: no NaN / Inf")


# ── Main ──────────────────────────────────────────────────────────────────────
print(f"\n{'='*60}")
print(f"  FUSED DATASET: {fused_name}")
print(f"  Positions  : {positions}")
print(f"  Target size: {target_n}  |  Expected channels: {n_channels}")
print(f"  Directory  : {fused_root}")
print(f"{'='*60}")

data_dir  = os.path.join(fused_root, "data")
label_dir = os.path.join(fused_root, "labels")

time_path   = os.path.join(data_dir,  "data_time_domain.npy")
freq_path   = os.path.join(data_dir,  "data_frequency_domain.npy")
label_path  = os.path.join(label_dir, "labels.npy")
groups_path = os.path.join(label_dir, "groups.npy")

# ── 1. File existence ─────────────────────────────────────────────────────────
print("\n-- File existence --")
missing = False
for p in [time_path, freq_path, label_path, groups_path]:
    if os.path.isfile(p):
        ok(os.path.basename(p))
    else:
        fail(f"MISSING: {p}")
        missing = True

if missing:
    print("\n[FAIL] Cannot continue — required files are missing.")
    sys.exit(1)

# ── 2. Load ───────────────────────────────────────────────────────────────────

time_arr = np.load(time_path)
labels   = np.load(label_path)
groups   = np.load(groups_path)
freq_arr = None
freq_loaded = True
try:
    freq_arr = np.load(freq_path)
except Exception as e:
    warn(f"Could not load frequency domain file: {e}. Skipping freq checks.")
    freq_loaded = False

print(f"\n-- Shapes --")

print(f"  time  : {time_arr.shape}")
if freq_loaded:
    print(f"  freq  : {freq_arr.shape}")
else:
    print(f"  freq  : [NOT LOADED]")
print(f"  labels: {labels.shape}")
print(f"  groups: {groups.shape}")

N = labels.shape[0]

# ── 3. Shape consistency ──────────────────────────────────────────────────────
print("\n-- Shape consistency --")

for name, arr in [("time", time_arr), ("groups", groups)]:
    if arr.shape[0] == N:
        ok(f"{name}.shape[0] == {N}")
    else:
        fail(f"{name}.shape[0] = {arr.shape[0]}, expected {N}")
if freq_loaded:
    if freq_arr.shape[0] == N:
        ok(f"freq.shape[0] == {N}")
    else:
        fail(f"freq.shape[0] = {freq_arr.shape[0]}, expected {N}")

# ── 4. Window & channel dimensions ───────────────────────────────────────────

print("\n-- Window & channel dimensions --")
exp_t = target_n
exp_f = target_n // 2

if time_arr.ndim == 3 and time_arr.shape[1] == exp_t:
    ok(f"time window = {time_arr.shape[1]} (expected {exp_t})")
else:
    fail(f"time window = {time_arr.shape[1] if time_arr.ndim==3 else '?'}, expected {exp_t}")

if freq_loaded:
    if freq_arr.ndim == 3 and freq_arr.shape[1] == exp_f:
        ok(f"freq window = {freq_arr.shape[1]} (expected {exp_f})")
    else:
        fail(f"freq window = {freq_arr.shape[1] if freq_arr.ndim==3 else '?'}, expected {exp_f}")

for name, arr in [("time", time_arr)]:
    ch = arr.shape[2] if arr.ndim == 3 else "?"
    if ch == n_channels:
        ok(f"{name} channels = {ch}  ({n_positions} positions × 8)")
    else:
        fail(f"{name} channels = {ch}, expected {n_channels} ({n_positions} × 8)")
if freq_loaded:
    ch = freq_arr.shape[2] if freq_arr.ndim == 3 else "?"
    if ch == n_channels:
        ok(f"freq channels = {ch}  ({n_positions} positions × 8)")
    else:
        fail(f"freq channels = {ch}, expected {n_channels} ({n_positions} × 8)")

# ── 5. NaN / Inf ──────────────────────────────────────────────────────────────

print("\n-- NaN / Inf checks --")
check_finite(time_arr, "time_domain")
if freq_loaded:
    check_finite(freq_arr, "freq_domain")

# ── 6. Label values ───────────────────────────────────────────────────────────
print("\n-- Label values --")
unique_labels = set(np.unique(labels).tolist())
invalid_labels = unique_labels - VALID_LABELS
if invalid_labels:
    fail(f"Unexpected label values: {invalid_labels}")
else:
    ok(f"All label values in {VALID_LABELS}")

# ── 7. Group IDs ─────────────────────────────────────────────────────────────
print("\n-- Group IDs --")
unique_groups = set(np.unique(groups).tolist())
invalid_groups = unique_groups - VALID_GROUPS
if invalid_groups:
    fail(f"Unexpected group IDs: {invalid_groups}")
else:
    ok(f"All group IDs valid")

missing_groups = VALID_GROUPS - unique_groups
if missing_groups:
    warn(f"Groups absent from fused dataset: {sorted(missing_groups)}")
else:
    ok(f"All 15 individuals present")

# ── 8. Class balance ──────────────────────────────────────────────────────────
print("\n-- Class balance --")
n_fall    = int((labels == 1).sum())
n_no_fall = int((labels == 0).sum())
ratio = n_fall / N if N > 0 else 0
print(f"  Total samples : {N}")
print(f"  Non-fall (0)  : {n_no_fall}  ({100*(1-ratio):.1f}%)")
print(f"  Fall     (1)  : {n_fall}  ({100*ratio:.1f}%)")
if ratio < 0.05:
    warn("Fall class is under 5% — very imbalanced")
elif ratio > 0.95:
    warn("Non-fall class is under 5% — very imbalanced")
else:
    ok("Class balance looks reasonable")

# ── 9. Per-group breakdown ────────────────────────────────────────────────────
print("\n-- Per-group sample counts --")
print(f"  {'ID':<6} {'total':>7} {'fall':>7} {'non-fall':>10} {'fall%':>7}")
print(f"  {'-'*6} {'-'*7} {'-'*7} {'-'*10} {'-'*7}")
for gid in sorted(unique_groups):
    mask     = groups == gid
    g_total  = int(mask.sum())
    g_fall   = int(labels[mask].sum())
    g_nofall = g_total - g_fall
    g_ratio  = 100 * g_fall / g_total if g_total > 0 else 0
    flag = " <-- no falls!" if g_fall == 0 else (" <-- no ADLs!" if g_nofall == 0 else "")
    print(f"  ID{gid:<4} {g_total:>7} {g_fall:>7} {g_nofall:>10} {g_ratio:>6.1f}%{flag}")

# ── 10. Cross-check vs individual single-sensor datasets ─────────────────────
print("\n-- Cross-check vs single-sensor datasets --")
any_single = False
for pos in positions:
    single_label_path = os.path.join(dataset_root, pos, "labels", "labels.npy")
    single_group_path = os.path.join(dataset_root, pos, "labels", "groups.npy")
    if not os.path.isfile(single_label_path):
        warn(f"{pos}: single-sensor labels.npy not found — skipping cross-check")
        continue
    any_single = True
    single_labels = np.load(single_label_path)
    single_groups = np.load(single_group_path) if os.path.isfile(single_group_path) else None
    print(f"\n  [{pos.upper()}] single-sensor N = {len(single_labels)},  fused N = {N}")
    if N > len(single_labels):
        warn(f"  Fused has MORE samples than single-sensor {pos} — unexpected")
    elif N < len(single_labels):
        diff = len(single_labels) - N
        ok(f"  Fused has fewer samples ({diff} fewer) — expected due to intersection matching")
    else:
        ok(f"  Same sample count as single-sensor {pos}")

    # per-group comparison
    if single_groups is not None:
        all_gids = sorted(set(np.unique(groups).tolist()) | set(np.unique(single_groups).tolist()))
        rows = []
        for gid in all_gids:
            f_count = int((groups == gid).sum())
            s_count = int((single_groups == gid).sum())
            rows.append((gid, s_count, f_count))
        print(f"    {'ID':<6} {'single':>8} {'fused':>8}")
        print(f"    {'-'*6} {'-'*8} {'-'*8}")
        for gid, s, f in rows:
            flag = "  <-- GAIN?" if f > s else ("  <-- LOSS" if f < s else "")
            print(f"    ID{gid:<4} {s:>8} {f:>8}{flag}")

if not any_single:
    warn("No single-sensor datasets found for cross-check. Run generate_datasets.py first.")

# ── Summary ───────────────────────────────────────────────────────────────────
print(f"\n{'='*60}")
if _any_fail:
    print("  RESULT: FAILED — see [FAIL] items above")
    sys.exit(1)
else:
    print("  RESULT: ALL CHECKS PASSED")
